import pandas as pd

def run(inputs: dict) -> dict:
    df = inputs['app_events'].copy()

    out_cols = ['user_id', 'session_num', 'session_start', 'session_end',
                'event_count', 'heartbeat_count']

    if df.empty:
        return {'user_sessions': pd.DataFrame(columns=out_cols)}

    df['event_ts'] = pd.to_datetime(df['event_ts'])
    df = df.sort_values(['user_id', 'event_ts', 'event_id'], kind='mergesort')

    threshold = pd.Timedelta(minutes=30)
    results = []

    for user_id, group in df.groupby('user_id', sort=False):
        session_num = 0
        open_session = None  # dict: session_num, start, last_activity, event_count, heartbeat_count

        for row in group.itertuples():
            ts = row.event_ts
            etype = row.event_type

            if etype in ('view', 'click', 'logout'):
                needs_new = (open_session is None) or ((ts - open_session['last_activity']) > threshold)

                if needs_new:
                    if open_session is not None:
                        results.append({
                            'user_id': user_id,
                            'session_num': open_session['session_num'],
                            'session_start': open_session['start'],
                            'session_end': open_session['last_activity'],
                            'event_count': open_session['event_count'],
                            'heartbeat_count': open_session['heartbeat_count'],
                        })
                    session_num += 1
                    open_session = {
                        'session_num': session_num,
                        'start': ts,
                        'last_activity': ts,
                        'event_count': 1,
                        'heartbeat_count': 0,
                    }
                else:
                    open_session['event_count'] += 1
                    open_session['last_activity'] = ts

                if etype == 'logout':
                    results.append({
                        'user_id': user_id,
                        'session_num': open_session['session_num'],
                        'session_start': open_session['start'],
                        'session_end': open_session['last_activity'],
                        'event_count': open_session['event_count'],
                        'heartbeat_count': open_session['heartbeat_count'],
                    })
                    open_session = None

            else:  # heartbeat
                if open_session is not None and (ts - open_session['last_activity']) <= threshold:
                    open_session['event_count'] += 1
                    open_session['heartbeat_count'] += 1
                # else: dropped, no effect

        if open_session is not None:
            results.append({
                'user_id': user_id,
                'session_num': open_session['session_num'],
                'session_start': open_session['start'],
                'session_end': open_session['last_activity'],
                'event_count': open_session['event_count'],
                'heartbeat_count': open_session['heartbeat_count'],
            })

    if not results:
        return {'user_sessions': pd.DataFrame(columns=out_cols)}

    result_df = pd.DataFrame(results, columns=out_cols)
    result_df = result_df.sort_values(['user_id', 'session_num'], kind='mergesort').reset_index(drop=True)

    return {'user_sessions': result_df}
